codeExample.code:
const stock = 3;
const available = stock > 0;
export default function Stock() {
  return <p>{available ? `${stock} disponible` : "Rupture"}</p>;
}

const stock = 3;
export default function Stock() {
  if (stock <= 0) return <p>Rupture</p>;
  return <p>{stock} disponible</p>;
}

